questionvariables.text:
/* Design: decide whether each statement is an identity: one PRT, four dropdowns, unique option values per slot. No item repeats a statement in the chapter text. Source: original. */
pool: [["\\sin^2 x + \\cos^2 x = 1",true,"This is the Pythagorean identity itself."],
 ["1 - \\cos^2 x = \\sin^2 x",true,"Rearrange \\(\\sin^2 x + \\cos^2 x = 1\\)."],
 ["\\cos^2 x - \\sin^2 x = 1 - 2\\sin^2 x",true,"Replace \\(\\cos^2 x\\) by \\(1 - \\sin^2 x\\)."],
 ["\\tan x \\cos x = \\sin x",true,"\\(\\tan x = \\dfrac{\\sin x}{\\cos x}\\), so \\(\\tan x \\cos x = \\sin x\\) wherever \\(\\cos x \\ne 0\\)."],
 ["\\sin^2 x - \\sin^4 x = \\sin^2 x \\cos^2 x",true,"Take out \\(\\sin^2 x\\): \\(\\sin^2 x(1 - \\sin^2 x) = \\sin^2 x\\cos^2 x\\)."],
 ["\\sin x - \\cos x = 1",false,"At \\(x = 0^\\circ\\) the left side is \\(0 - 1 = -1\\)."],
 ["2\\sin^2 x + \\cos^2 x = 1",false,"At \\(x = 90^\\circ\\) the left side is \\(2 + 0 = 2\\)."],
 ["\\sin^2 x = 1 - \\cos x",false,"At \\(x = 180^\\circ\\) the left side is \\(0\\) and the right side is \\(2\\)."],
 ["\\sin^2 x - \\cos^2 x = 1",false,"At \\(x = 0^\\circ\\) the left side is \\(0 - 1 = -1\\)."],
 ["(\\cos x - \\sin x)^2 = 1",false,"At \\(x = 45^\\circ\\) the left side is \\(0\\)."]];
sel: [[1,6,3,9],[7,2,10,4],[5,8,6,2],[9,3,5,7],[4,10,8,1],[6,7,2,5],[3,4,8,10],[9,1,7,3],[2,10,4,6],[8,5,9,1]];
ix: 1+rand(10);
S: sel[ix];
st1: pool[S[1]][1]; is1: pool[S[1]][2]; tx1: pool[S[1]][3];
st2: pool[S[2]][1]; is2: pool[S[2]][2]; tx2: pool[S[2]][3];
st3: pool[S[3]][1]; is3: pool[S[3]][2]; tx3: pool[S[3]][3];
st4: pool[S[4]][1]; is4: pool[S[4]][2]; tx4: pool[S[4]][3];
opt1: [["id1", is1, "identity"], ["no1", not is1, "not an identity"]];
opt2: [["id2", is2, "identity"], ["no2", not is2, "not an identity"]];
opt3: [["id3", is3, "identity"], ["no3", not is3, "not an identity"]];
opt4: [["id4", is4, "identity"], ["no4", not is4, "not an identity"]];
ta1: first(mcq_correct(opt1)); ta2: first(mcq_correct(opt2)); ta3: first(mcq_correct(opt3)); ta4: first(mcq_correct(opt4));
wa1: first(mcq_incorrect(opt1)); wa2: first(mcq_incorrect(opt2)); wa3: first(mcq_incorrect(opt3)); wa4: first(mcq_incorrect(opt4));
isl: [is1, is2, is3, is4];

feedbackvariables.text:
ok1: is(ans1 = ta1);
ok2: is(ans2 = ta2);
ok3: is(ans3 = ta3);
ok4: is(ans4 = ta4);
okl: [ok1, ok2, ok3, ok4];
wrongE_only: every(lambda([k], okl[k] or not isl[k]), [1,2,3,4]) and some(lambda([k], not okl[k] and not isl[k]), [1,2,3,4]);
wrongI_only: every(lambda([k], okl[k] or isl[k]), [1,2,3,4]) and some(lambda([k], not okl[k] and isl[k]), [1,2,3,4]);
nE: length(sublist([1,2,3,4], lambda([k], not okl[k] and not isl[k])));
nI: length(sublist([1,2,3,4], lambda([k], not okl[k] and isl[k])));
